// CXXRTL backend: gen/uds_chip_cxxrtl.cc, generated by Yosys write_cxxrtl -O6.
//
// One eval() + commit() per clock: the clock is set high, eval() computes the
// next state from the current one, commit() makes it current, and the clock
// goes low again without a second evaluation (no logic runs on the falling
// edge). The outputs read after commit() were computed by eval() from the
// state before the edge, so they are the pins during the cycle just clocked.
//
// SPDX-License-Identifier: Apache-2.0
#pragma once
#ifndef CXXRTL_SOURCE
#define CXXRTL_SOURCE "gen/uds_chip_cxxrtl.cc"   // CXXRTL_SOURCE: another chip variant (build.sh sd2)
#endif
#include CXXRTL_SOURCE

#define BACKEND_NAME "cxxrtl"
#define BACKEND_ID 1

namespace backend {

cxxrtl_design::p_tt__um__ai__wrangler__uds1x1 chip;
uint8_t uo = 0, uio = 0;

inline void init() {
  chip.p_ena.set<bool>(true);
  chip.p_ui__in.set<uint8_t>(0);
}
inline void set_rst_n(bool v) { chip.p_rst__n.set<bool>(v); }

// One clock cycle with these inputs; afterwards uo/uio are the pins during it.
inline void clock(uint8_t uio_in) {
  chip.p_uio__in.set<uint8_t>(uio_in);
  chip.p_clk.set<bool>(true);
  chip.eval();
  chip.commit();
  chip.p_clk.set<bool>(false);
  chip.prev_p_clk = chip.p_clk;
  uo = chip.p_uo__out.get<uint8_t>();
  uio = chip.p_uio__out.get<uint8_t>();
}

}  // namespace backend
